"""Freeze scope after a one-day exploratory archive/schema pilot, before main execution."""
import datetime as dt, hashlib, json, re, tarfile
from pathlib import Path
from pypdf import PdfReader
ROOT=Path(__file__).resolve().parent
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def save(path,obj):
 p=ROOT/path;p.parent.mkdir(parents=True,exist_ok=True)
 raw=(json.dumps(obj,indent=2,ensure_ascii=False,allow_nan=False)+'\n').encode()
 if p.exists() and p.read_bytes()!=raw:raise RuntimeError(f'Immutable file differs: {p}')
 p.write_bytes(raw)
def main():
 paper=PdfReader(ROOT/'raw/main.pdf')
 text='\n'.join(p.extract_text() for p in paper.pages[13:15])
 text=text.split('References',1)[1].split('\nA Ethics',1)[0]
 refs=re.findall(r'\[(\d+)\]\s+(.*?)(?=\n\[\d+\]|\Z)',text,re.S)
 assert [int(n) for n,_ in refs]==list(range(1,73))
 sources=[]
 for n,c in refs:
  c=re.sub(r'\s+',' ',c).strip();c=c.replace('https: //','https://').replace('http: //','http://')
  urls=re.findall(r'https?://\S+',c);doi=re.search(r'10\.\d{4,9}/[^\s]+',c)
  rfc=re.search(r'RFC\s*(\d+)',c)
  if rfc:
   url=f'https://www.rfc-editor.org/rfc/rfc{rfc.group(1)}.txt';kind='standard'
  elif doi:url='https://doi.org/'+doi.group(0).rstrip('.');kind='research'
  else:url=urls[0] if urls else None;kind='documentation' if url else 'research'
  sources.append(dict(reference_number=int(n),citation=c,doi=doi.group(0).rstrip('.') if doi else None,kind=kind,source_url=url,role='Direct contextual citation; role refined by explicit review.',review_status='unavailable-full-text',access_status='not-attempted',retrieval_attempts=[],findings=None,limitations='No substantive review yet.',reviewer=dict(identity='Codex primary assistant',type='AI',independence='Same study implementer; no human review')))
 save('evidence/source-seeds-v1.json',sources)
 member=[]
 with tarfile.open(ROOT/'raw/measurement_scripts_and_configs.tar.gz') as archive:
  for item in archive.getmembers():
   if item.isfile():
    b=archive.extractfile(item).read();member.append(dict(path=item.name,bytes=len(b),sha256=hashlib.sha256(b).hexdigest()))
 save('evidence/author-members-v1.json',member)
 now=dt.datetime.now(dt.timezone.utc).isoformat()
 common=dict(version=1,locked_at=now,reviewer={'identity':'Codex primary assistant','type':'AI','independence':'Implementer'},paper_sha256=sha(ROOT/'raw/main.pdf'),artifact_sha256=sha(ROOT/'raw/measurement_scripts_and_configs.tar.gz'),pilot='2025-09-14 summaries inspected for schema and feasibility only before this lock. Main results are not held out from this pilot.',resource_limits={'concurrency':4,'request_timeout_seconds':40,'max_artifact_bytes':20_000_000,'main_download_limit_bytes':150_000_000,'AWS_experiment_instances':0,'estimated_incremental_AWS_experiment_compute_usd':0,'local_cost_usd':None,'storage_charges_usd':None,'stopping_rule':'Visit every planned daily input twice at most; retain failed attempts. Stop at size limit or integrity failure; do not replace historical conditions with current scans.'})
 protocol=dict(common,id='ipv6-dns-archive-v1',stage='main',questions=['Do released daily summaries reproduce the rounded absolute cells of Figures 13–15?','How do IPv6-minus-IPv4 differences vary by matched configuration and epoch?','Does day weighting versus denominator pooling materially change results?'],experiment_type='Reanalysis of authors recorded summaries; author implementation folding plus independent arithmetic',epochs={'tcp-error':['2025-04-10','2025-05-23'],'pre-lgi':['2025-05-25','2025-06-14'],'current':['2025-06-25','2025-09-14']},input_range=['2025-04-10','2025-09-14'],inputs=['out_data/{date}/stats/all_psl_domains.json.gz','pcap_agregates/{date}.json'],input_base_url='https://data.measurement.network/dns-mtu-msmt/',configurations={'mtu':['mtu1500','mtu1280-pmtud','mtu1280-nopmtud','mtu1280onpath-nopmtud'],'address_family':['v4-only','v6-only','ds'],'upstream':['lgi','no-lgi'],'edns_bytes':[512,1232,4096],'cohort':['dnssec','no-dnssec']},metrics={'TIMEOUT':'100*status_count/NS-set_count, percent','SERVFAIL':'100*status_count/NS-set_count, percent','edns0_fallback':'100*client_edns_fallback/UDP_count, percent of observed UDP server identities','tcp_fallback':'100*TCP_count/UDP_count, percent ratio; not fraction of mutually exclusive events','udp_fragments':'100*UDP_frag/UDP_count, percent of observed UDP server identities','udp_packet_too_big':'100*UDP_packet_too_big/UDP_count, percent'},comparison={'absolute_cell_tolerance_percentage_points':0.0051,'relative_value_unit':'percentage points','agreement_is':'Numerical agreement with printed rounded values only, not correctness or broad validation'},replication_unit='Daily aggregate and matched configuration/date. NS sets, servers, paths and repeated days are correlated; daily counts are observation coverage, not independent replications.',sample_size_rationale='Census of all 158 calendar dates in publication interval; all grid configurations retained. Three declared epochs include 147 calendar days. No power or iid sample-size claim.',exclusions={'2025-04-21':'Missing archive day; retain missing status','2025-05-20/2025-05-24':'Known routing anomaly; original early figure window preserved, exclude in separately labeled routing sensitivity','2025-06-15/2025-06-24':'Provider policy transition; retained but outside fixed epochs','2025-05-24':'Outside printed epoch windows; retained'},missing_rules='Absent numerator or zero denominator is missing/invalid, not measured zero. Explicit recorded zero is retained. Source cohort/identity mismatches are ambiguous; no merging by order. Published author zero-imputation reproduced separately only for author fidelity.',statistics='Unweighted mean of recorded daily percentages matches released figure fold. Sensitivity pools numerators/denominators on same valid days, and removes routing-anomaly dates. Report min/max descriptive daily range and matched-date IPv6-minus-IPv4 contrasts. No inferential CI: changing, clustered convenience panel and raw dependence structure unavailable.',algorithms_and_seeds='Deterministic arithmetic; RNG and orbital/terminal inputs inapplicable. Historical random representative-domain selection cannot be replayed without original selections.',controls=['Counts finite/nonnegative/integer; statuses sum to cohort count; cohort partition equals all; grid and identity validation; numerator<=denominator where appropriate, TCP/UDP ratio can exceed100.','Execute AST-extracted original read_files with constrained filesystem adapter; compare independent summaries to original fold. Shared input summaries imply shared upstream aggregation assumptions.'],coverage_limits=['No new network measurements, packet-drop causal experiment, live operational validation or APNIC raw-data reanalysis.','No full raw-pcap replay: published daily volumes exceed local budget.','Server-IP denominators differ from NS-set outcome denominators; do not treat them as interchangeable.','Published revisions/2025 routes cannot be inferred from archive release timestamps.'],applicability={'simulations':'inapplicable: DNS empirical measurement paper','orbital_epochs':'inapplicable','equipment':'BGP-controlled paths and historical operator policy unavailable; no fresh network campaign proposed','best_case_vs_budget':'Census fixed archive window; no best-day selection; full raw replay outside150MB input budget'})
 controls=dict(common,id='ipv6-dns-controls-v1',stage='correctness',questions=['Does released aggregation discard earlier distinct answers?','Does a field named duration_avg use max?','Can answer hashing merge differing status-only records?'],metrics={'retained_records':'integer','duration':'seconds','status':'categorical'},inputs='Finite fabricated unit fixtures, clearly separated from network measurements',configurations=['same name two distinct NS answers','same answers statuses NOERROR/TIMEOUT','durations1 and3 seconds','empty durations'],hypotheses='Released code may reset distinct answer groups, merge status-only differences, and report max3 as average instead of2. Test observed output before drawing conclusions.',controls='Independent specification preserving every observation and computing arithmetic mean; preserve unmodified source AST functions and source hash. Correction in separate version; do not alter archive.',sample_size_rationale='Exhaustive declared finite cases, no stochastic replications',statistics='Deterministic exact comparisons; confidence intervals inapplicable',exclusions='Failed code executions recorded; empty duration should remain invalid/missing rather than zero',coverage_limits='A finite code defect does not prove impact on published results; actual generating revision and observation ordering unavailable.')
 for p in [protocol,controls]:
  path=ROOT/f'protocols/{p["id"]}.json'
  if not path.exists():save(str(path.relative_to(ROOT)),p)
  save(f'protocols/{p["id"]}.lock.json',dict(id=p['id'],sha256=sha(path),locked_at=json.loads(path.read_text())['locked_at']))
 print(json.dumps(dict(sources=len(sources),archive_files=len(member),protocols=['ipv6-dns-archive-v1','ipv6-dns-controls-v1'])))
if __name__=='__main__':main()
